using System;
using System.Drawing;
using System.Drawing.Drawing2D;
using System.Drawing.Imaging;
using System.IO;
class PackAppIcon {
 static Bitmap Render(Image source,int size){var b=new Bitmap(size,size,PixelFormat.Format32bppArgb);using(var g=Graphics.FromImage(b)){g.Clear(Color.Transparent);g.CompositingMode=CompositingMode.SourceCopy;g.InterpolationMode=InterpolationMode.HighQualityBicubic;g.PixelOffsetMode=PixelOffsetMode.HighQuality;using(var wrap=new ImageAttributes()){wrap.SetWrapMode(WrapMode.TileFlipXY);g.DrawImage(source,new Rectangle(0,0,size,size),0,0,source.Width,source.Height,GraphicsUnit.Pixel,wrap);}}return b;}
 static byte[] Dib(Bitmap b){int size=b.Width,stride=((size+31)/32)*4;using(var m=new MemoryStream())using(var w=new BinaryWriter(m)){w.Write(40);w.Write(size);w.Write(size*2);w.Write((ushort)1);w.Write((ushort)32);w.Write(0);w.Write(size*size*4);w.Write(0);w.Write(0);w.Write(0);w.Write(0);for(int y=size-1;y>=0;y--)for(int x=0;x<size;x++){Color c=b.GetPixel(x,y);w.Write(c.B);w.Write(c.G);w.Write(c.R);w.Write(c.A);}for(int y=size-1;y>=0;y--){byte[] mask=new byte[stride];for(int x=0;x<size;x++)if(b.GetPixel(x,y).A==0)mask[x/8]|=(byte)(0x80>>(x%8));w.Write(mask);}return m.ToArray();}}
 static void Main(string[] args){using(var source=Image.FromFile(args[0])){string folder=args[1];int[] sizes={16,20,24,32,40,48,64,96,128,256};var payloads=new byte[sizes.Length][];for(int i=0;i<sizes.Length;i++)using(var b=Render(source,sizes[i]))using(var m=new MemoryStream()){b.Save(m,ImageFormat.Png);payloads[i]=sizes[i]<256?Dib(b):m.ToArray();if(sizes[i]==256)b.Save(Path.Combine(folder,"HPRGhostReplay-256.png"),ImageFormat.Png);}
 using(var w=new BinaryWriter(File.Create(Path.Combine(folder,"HPRGhostReplay.ico")))){w.Write((ushort)0);w.Write((ushort)1);w.Write((ushort)sizes.Length);int offset=6+16*sizes.Length;for(int i=0;i<sizes.Length;i++){w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)(sizes[i]==256?0:sizes[i]));w.Write((byte)0);w.Write((byte)0);w.Write((ushort)1);w.Write((ushort)32);w.Write(payloads[i].Length);w.Write(offset);offset+=payloads[i].Length;}foreach(var bytes in payloads)w.Write(bytes);}
 using(var board=new Bitmap(960,450))using(var g=Graphics.FromImage(board))using(var title=new Font("Segoe UI",22))using(var text=new Font("Segoe UI",11))using(var white=new SolidBrush(Color.FromArgb(242,242,242)))using(var muted=new SolidBrush(Color.FromArgb(174,180,190))){g.Clear(Color.FromArgb(32,32,32));g.DrawString("HPRGhostReplay",title,white,30,20);g.DrawString("Original HPR Steam mark + translucent ghost",text,muted,32,67);using(var large=Render(source,256))g.DrawImageUnscaled(large,42,120);int x=352;foreach(int size in new int[]{16,24,32,48,64}){using(var icon=Render(source,size))g.DrawImageUnscaled(icon,x,140+(64-size)/2);g.DrawString(size+" px",text,muted,x,216);x+=110;}g.FillRectangle(Brushes.White,352,273,576,130);int pos=380;foreach(int size in new int[]{96,48,32,16}){using(var icon=Render(source,size))g.DrawImageUnscaled(icon,pos,288+(96-size)/2);pos+=120;}board.Save(Path.Combine(folder,"HPRGhostReplay-icon-preview.png"),ImageFormat.Png);}
 }}
}
